86	    @Test
87	    void revokeAndReleaseConcurrentFollowCommitOrder() throws Exception {
88	        // 重复多轮，验证任意调度下都不出现“撤销后仍被放行”
89	        for (int round = 0; round < 15; round++) {
90	            final int r = round;
91	            String certBody = mvc.perform(post("/api/certificates")
92	                            .contentType(MediaType.APPLICATION_JSON)
93	                            .content("""
94	                                    {"instrumentId":"INS-R%d","validFrom":"2026-01-01T00:00:00Z",
95	                                     "validTo":"2028-01-01T00:00:00Z","a":"1","b":"0"}""".formatted(r)))
96	                    .andReturn().getResponse().getContentAsString();
97	            long certId = ((Number) com.jayway.jsonpath.JsonPath.read(certBody, "$.id")).longValue();
98	
99	            mvc.perform(post("/api/measurements")
100	                    .contentType(MediaType.APPLICATION_JSON)
101	                    .content("""
102	                            {"measurementKey":"M-%d","instrumentId":"INS-R%d",
103	                             "measuredAt":"2026-06-01T00:00:00Z","reading":"1",
104	                             "lowerLimit":"0","upperLimit":"9","submittedBy":"alice"}""".formatted(r, r)))
105	                    .andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isCreated());
106	
107	            ExecutorService pool = Executors.newFixedThreadPool(2);
108	            CountDownLatch start = new CountDownLatch(1);
109	            Future<Integer> revokeFuture = pool.submit(() -> {
110	                start.await();
111	                return mvc.perform(post("/api/certificates/{id}/revoke", certId))
112	                        .andReturn().getResponse().getStatus();
113	            });
114	            Future<Integer> releaseFuture = pool.submit(() -> {
115	                start.await();
116	                return mvc.perform(post("/api/measurements/release")
117	                                .header("X-Actor-Id", "carol")
118	                                .contentType(MediaType.APPLICATION_JSON)
119	                                .content("{\"keys\":[\"M-" + r + "\"]}"))
120	                        .andReturn().getResponse().getStatus();
121	            });
122	            start.countDown();
123	            int revokeStatus = revokeFuture.get(30, TimeUnit.SECONDS);
124	            int releaseStatus = releaseFuture.get(30, TimeUnit.SECONDS);
125	            pool.shutdown();
126	            assertEquals(200, revokeStatus);
127	            assertTrue(releaseStatus == 200 || releaseStatus == 409);
128	
129	            Map<String, Object> cert = jdbc.queryForMap("SELECT * FROM calibration_certificate WHERE id = ?", certId);
130	            Map<String, Object> measurement = jdbc.queryForMap(
131	                    "SELECT * FROM measurement WHERE measurement_key = ?", "M-" + r);
132	            Integer releaseCount = jdbc.queryForObject(
133	                    "SELECT COUNT(*) FROM release_record WHERE measurement_id = ?",
134	                    Integer.class, ((Number) measurement.get("id")).longValue());
135	
136	            if (releaseCount > 0) {
137	                // 放行先提交：历史必须保留，状态为 RELEASED；撤销在其后生效
138	                assertEquals("RELEASED", measurement.get("status"));
139	                java.sql.Timestamp revokedAt = (java.sql.Timestamp) cert.get("revoked_at");
140	                Map<String, Object> release = jdbc.queryForMap(
141	                        "SELECT * FROM release_record WHERE measurement_id = ?",
142	                        ((Number) measurement.get("id")).longValue());
143	                assertFalse(((java.sql.Timestamp) release.get("released_at"))
144	                        .after(revokedAt), "撤销提交后不得再放行该证书下的结果");
145	            } else {
146	                // 撤销先提交：放行必须 409，测量保持待放行
147	                assertEquals(409, releaseStatus);
148	                assertEquals("PENDING", measurement.get("status"));
149	            }
150	        }
151	    }
152	
153	    @Test
154	    void concurrentReleaseSameMeasurementExactlyOneWins() throws Exception {
155	        String certBody = mvc.perform(post("/api/certificates")
156	                        .contentType(MediaType.APPLICATION_JSON)
157	                        .content("""
158	                                {"instrumentId":"INS-D","validFrom":"2026-01-01T00:00:00Z",
159	                                 "validTo":"2028-01-01T00:00:00Z","a":"1","b":"0"}"""))
160	                .andReturn().getResponse().getContentAsString();
161	        mvc.perform(post("/api/measurements")
162	                .contentType(MediaType.APPLICATION_JSON)
163	                .content("""
164	                        {"measurementKey":"M-D","instrumentId":"INS-D",
165	                         "measuredAt":"2026-06-01T00:00:00Z","reading":"1",
166	                         "lowerLimit":"0","upperLimit":"9","submittedBy":"alice"}"""))
167	                .andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isCreated());
168	
169	        int threads = 6;
170	        ExecutorService pool = Executors.newFixedThreadPool(threads);
171	        CountDownLatch start = new CountDownLatch(1);
172	        List<Future<Integer>> results = new ArrayList<>();
173	        for (int i = 0; i < threads; i++) {
174	            results.add(pool.submit(() -> {
175	                start.await();
176	                return mvc.perform(post("/api/measurements/release")
177	                                .header("X-Actor-Id", "carol")
178	                                .contentType(MediaType.APPLICATION_JSON)
179	                                .content("{\"keys\":[\"M-D\"]}"))
180	                        .andReturn().getResponse().getStatus();
181	            }));
182	        }
183	        start.countDown();
184	        AtomicInteger ok = new AtomicInteger();
185	        AtomicInteger conflict = new AtomicInteger();
186	        for (Future<Integer> future : results) {
187	            int status = future.get(30, TimeUnit.SECONDS);
188	            if (status == 200) {
