192	            }
193	        }
194	        pool.shutdown();
195	        assertEquals(1, ok.get(), "并发重复放行必须恰好一批成功");
196	        assertEquals(threads - 1, conflict.get());
197	        Integer releaseCount = jdbc.queryForObject(
198	                "SELECT COUNT(*) FROM release_record r JOIN measurement m ON m.id = r.measurement_id "
199	                        + "WHERE m.measurement_key = 'M-D'", Integer.class);
200	        assertEquals(1, releaseCount, "只允许写入一条放行历史");
201	    }
