30	    static BigDecimal requireDecimal(String value, String field) {
31	        if (value == null || !DECIMAL.matcher(value.trim()).matches()) {
32	            throw ApiException.badRequest(field + " 必须为最多 6 位小数的十进制字符串");
33	        }
34	        return new BigDecimal(value.trim());
35	    }
36	
37	    static Instant requireInstant(String value, String field) {
38	        if (value == null || value.isBlank()) {
39	            throw ApiException.badRequest(field + " 不能为空");
40	        }
41	        try {
42	            return OffsetDateTime.parse(value.trim(), DateTimeFormatter.ISO_OFFSET_DATE_TIME).toInstant();
43	        } catch (DateTimeParseException ex) {
44	            throw ApiException.badRequest(field + " 必须为带时区的 ISO-8601 时间");
